class Solution:

	def findDuplicate(self, nums):
		if len(nums) == 0:
			return None
		slow = fast = nums[0]
		while True:
			slow = nums[slow]
			fast = nums[nums[fast]]
			if slow == fast:
				break
		fast = nums[0]
		while slow != fast:
			slow = nums[slow]
			fast = nums[fast]
		return slow
